const rpc=async(fn,args)=>{let r;try{r=await fetch(SB.url+'/rest/v1/rpc/'+fn,{method:'POST',headers:{apikey:SB.key,Authorization:'Bearer '+SB.key,'Content-Type':'application/json'},body:JSON.stringify(args)})}catch(e){const x=new Error('Cannot reach the server. Please check the internet connection.');x.net=1;throw x}
 let j=null;try{j=await r.json()}catch(e){}
 if(!r.ok){const x=new Error((j&&j.message)||'Server error');x.status=r.status;throw x}return j};
const kj=o=>{const r={};for(const k in o)r[k]=JSON.stringify(o[k]);return r};
const dff=(o,b)=>{const patch={},next={};let n=0;for(const k in o){const j=JSON.stringify(o[k]);next[k]=j;if(b[k]!==j){patch[k]=o[k];n++}}return {patch,next,n}};
