async function push(){if(!SB.on||!tok||!user)return;if(syncing){again=true;return}syncing=true;
 try{do{again=false;
  if(user.role=='student'){const s=stu(user.id);if(s&&bS[s.id]){const d=dff(s,bS[s.id]);if(d.n){await rpc('rr_save',{t:tok,sid:s.id,patch:d.patch,cls:null});bS[s.id]=d.next}}}
  else if(user.role=='teacher'){for(const s of P.students){if(!bS[s.id])continue;const d=dff(s,bS[s.id]);if(d.n){await rpc('rr_save',{t:tok,sid:s.id,patch:d.patch,cls:null});bS[s.id]=d.next}}
   const c=dff(clsObj(),bC);if(c.n){await rpc('rr_save',{t:tok,sid:null,patch:null,cls:c.patch});bC=c.next}}
 }while(again);stat(1)}
 catch(e){if(noSess(e))expired();else if(e.status==400&&/FORBIDDEN/.test(e.message)){try{await pull(true);render();stat(1)}catch(x){stat(3)}}else stat(e.net?2:3)}finally{syncing=false}}
function apply(d){P.teachers=d.teachers||[];P.students=d.students||[];P.parents=d.parents||[];const c=d.cls||{};P.pace=c.pace;P.stories=c.stories;fixP();bS={};P.students.forEach(s=>bS[s.id]=kj(s));bC=kj({pace:c.pace,stories:c.stories})}
