// Audio: prefers a Kenyan English female voice, then other East/West/South African English female voices, then any English female voice.
const FEM=/female|zira|samantha|susan|hazel|karen|moira|tessa|fiona|aria|jenny|libby|sonia|natasha|ava|serena|catherine|heera|veena/i;
function voice(){try{const en=speechSynthesis.getVoices().filter(x=>/^en/i.test(x.lang));return en.find(x=>/en[-_]KE/i.test(x.lang))||en.find(x=>/en[-_](TZ|UG|NG|ZA)/i.test(x.lang)&&FEM.test(x.name))||en.find(x=>FEM.test(x.name)&&/en[-_](GB|ZA|IN|AU)/i.test(x.lang))||en.find(x=>FEM.test(x.name))||en.find(x=>/en[-_](GB|ZA|IN)/i.test(x.lang))||en[0]}catch(e){}}
const spoken=x=>SND[String(x).toLowerCase()]||x;
// A sound is spoken as its sound, then a pause, then an example word: "muh. mama."
const NAME={a:'ay',b:'bee',c:'see',d:'dee',e:'ee',f:'eff',g:'jee',h:'aitch',i:'eye',j:'jay',k:'kay',l:'el',m:'em',n:'en',o:'oh',p:'pee',q:'kyoo',r:'are',s:'ess',t:'tee',u:'yoo',v:'vee',w:'double you',x:'ex',y:'why',z:'zed'};
const phrase=x=>{if(typeof x!='string'||x.includes(' '))return x;const k=x.toLowerCase();if(k.length==1&&NAME[k])return NAME[k];return SND[k]!==undefined?SND[k]+'. '+(EX[k]||''):x};
window.say=(t,r)=>{try{speechSynthesis.cancel();const v=voice();t=String(t);const parts=t.length>120?(t.match(/[^.!?]+[.!?]+[”"]?/g)||[t]):[t];parts.forEach(z=>{const u=new SpeechSynthesisUtterance(z.trim());if(v)u.voice=v;u.lang=(v&&v.lang)||'en-KE';u.rate=r||.75;u.pitch=1.15;speechSynthesis.speak(u)})}catch(e){}};
try{speechSynthesis.onvoiceschanged=()=>{}}catch(e){}
