const pad2=n=>String(n).padStart(2,'0'),ymd=d=>`${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;
const weekKey=()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return ymd(d)};
const weekN=s=>s.wk&&s.wk.w==weekKey()?s.wk.n:0;
const canNew=s=>!P.pace.perWeek||weekN(s)<P.pace.perWeek;
const bumpWk=s=>{s.wk={w:weekKey(),n:weekN(s)+1}};
const clean=t=>String(t==null?'':t).replace(/[<>]/g,'').replace(/\s*\n\s*/g,' ').trim();
const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const chkName=()=>P.pace.checkDay===4?'Friday check':'Weekly check';
const weeklyPool=s=>{const mc=[],ls=[];acts(s.g,s.lv).forEach((a,k)=>{if(!s.done.includes(aid(s.g,s.lv,k)))return;const strs=a.i.filter(x=>typeof x=='string'&&x.length<=30);a.i.forEach(x=>{if(x.t=='mcq')mc.push(x);else if(typeof x=='string'&&x.length<=30&&strs.length>=3){ls.push({t:'mcq',q:'Listen. What did you hear?',o:[x,...shuf(strs.filter(y=>y!=x)).slice(0,2)],p:x,hide:1})}})});return [...mc,...ls]};
const checkOpen=s=>{if((s.weekly||[]).some(c=>c.w==weekKey()))return false;const cd=P.pace.checkDay;if(cd!=='any'&&(new Date().getDay()+6)%7<+cd)return false;return weeklyPool(s).length>=2};
